use moloch_replay::{session::Session,Side};
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,path::PathBuf};
const BASE:i64=1_792_054_800_000;
fn iso(t:i64)->String{chrono::DateTime::from_timestamp_millis(BASE+t).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
struct F{split:bool,root:PathBuf,bank:Option<Session>,policy:Value,seed:Value}
impl Drop for F{fn drop(&mut self){self.bank.take();let _=fs::remove_dir_all(&self.root);}}
impl F{
 fn new()->Self{
  let root=std::env::temp_dir().join(format!("passive-cohort-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir(&root).unwrap();
  let policy=json!({"initialCash":"100.000000","maximumCommitted":"20.000000","maximumMarketCost":"10.000000","quantity":100,"maximumMarkets":3,"minimumSpreadTicks":10,"requireCurrentFlow":true,"entryStopAt":iso(120000)});
  let seed=json!({"runId":"reviewed-entry-fixture","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});
  let bank=Session::open_live(&root.join("bank"),&policy,&seed).unwrap();let mut f=Self{split:true,root,bank:Some(bank),policy,seed};f.book(0,"0.400000");f
 }
 fn b(&self)->&Session{self.bank.as_ref().unwrap()}
 fn accept(&mut self,e:&Value)->Result<bool,Box<dyn std::error::Error>>{let n=self.b().last_source_sequence("fixture")+1;self.bank.as_mut().unwrap().accept("fixture",n,e)}
 fn bound(&self,t:i64,kind:&str)->Value{json!({"type":kind,"source":"moloch_live_dispatcher","bankScope":{"runId":"reviewed-entry-fixture","bankManifestHash":self.b().manifest_hash(),"tournamentId":"cup"},"bankHead":self.b().durable_head(),"expectedReportSha256":hash(&self.b().engine().report().unwrap()),"receivedAt":iso(t),"processedAt":iso(t)})}
 fn book(&mut self,t:i64,bid:&str){let n=self.b().last_source_sequence("books")+1;self.bank.as_mut().unwrap().accept("books",n,&json!({"type":"book","receivedAt":iso(t),"book":{"marketId":"201","exchangeId":"101","tournamentId":"cup","sequence":n.to_string(),"sourceAt":iso(t),"requestStartedAt":iso(t),"receivedAt":iso(t),"bids":[{"price":bid,"quantity":100}],"asks":[{"price":if bid=="0.400000"{"0.405000"}else{"0.605000"},"quantity":100}]}})).unwrap();}
 fn mode(&self,t:i64)->Value{let mut e=self.bound(t,"managed_inventory_planning_v1");e["managedExchangeIds"]=json!(["101"]);e["approvedReviewSetSha256"]=json!("b".repeat(64));e["generationSha256"]=json!("0".repeat(64));e["controlSha256"]=json!("c".repeat(64));e["expectedPreviousModeSha256"]=self.b().engine().managed_inventory_planning_record().map_or(Value::Null,|r|r["sha256"].clone());e}
 fn close(&mut self,q:&Value,t:i64,actual:&str,n:u64){let mut e=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":q["id"],"actualOrderId":actual,"marketId":"201","exchangeId":"101","side":"YES","action":q["action"],"price":q["price"],"quantity":q["quantity"],"receivedAt":iso(t)});self.accept(&e).unwrap();e["type"]=json!("actual_fill");e["fillId"]=json!((actual.parse::<u64>().unwrap()*10+1).to_string());e["quantity"]=json!(n);e["executedAt"]=json!(iso(t));e["fee"]=json!(if q["action"]=="buy"{"0.000001"}else{"0.000000"});
 if self.split&&q["action"]=="buy"&&n==2{e["quantity"]=json!(1);e["fee"]=json!("0.000001");self.accept(&e).unwrap();e["fillId"]=json!((actual.parse::<u64>().unwrap()*10+2).to_string());e["price"]=json!("0.395000");e["fee"]=json!("0.000000");self.accept(&e).unwrap();}else{self.accept(&e).unwrap();}e["type"]=json!("actual_order_terminal");e["status"]=json!("canceled");e["filledQuantity"]=json!(n);e["fillsComplete"]=json!(true);self.accept(&e).unwrap();}
 fn position(&mut self)->Value{let mut e=self.bound(3000,"reviewed_fundamental_entry_reserved_v1");for(k,v)in json!({"originSha256":"a".repeat(64),"reviewSha256":"b".repeat(64),"bookSha256":hash(&self.b().engine().live_package_books()[0]),"reviewCurrentUntilMs":BASE+120000,"marketId":"201","exchangeId":"101","side":"YES","limitPrice":"0.400000","expectedPayout":"0.600000","marginPerShare":"0.010000","reviewMaximumQuantity":2,"reviewMaximumPrincipal":"10.000000","expiresAt":iso(60000)}).as_object().unwrap(){e[k]=v.clone();}self.accept(&e).unwrap();let q=self.b().engine().order_records()[0].clone();self.close(&q,6001,"901",2);self.cleanup(6200);q}
 fn cleanup(&mut self,t:i64){for q in self.b().engine().order_records().into_iter().filter(|q|q["retired"]==false){assert!(!self.b().engine().live_order_bindings().contains_key(&q["id"].as_u64().unwrap()));self.accept(&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":q["id"],"confirmedNetworkAttempts":0,"receiptHash":"e".repeat(64),"deferPlanningForPackage":true,"receivedAt":iso(t)})).unwrap();}}
 fn row(q:&Value,actual:&str,n:u64)->Value{json!({"qid":q["id"],"actualOrderId":actual,"filledQuantity":n,"bindingSha256":"d".repeat(64),"closedDispatchSha256":"e".repeat(64)})}
 fn exit(&self,t:i64,entries:Value,exits:Value,n:u64)->Value{let mut e=self.bound(t,"reviewed_cohort_exit_reserved_v1");let positions=self.b().engine().wallet.positions();for(k,v)in json!({"originSha256":"a".repeat(64),"reviewSha256":"b".repeat(64),"bookSha256":hash(&self.b().engine().live_package_books()[0]),"expectedPositionSha256":hash(&positions["101"]),"reviewCurrentUntilMs":BASE+120000,"marketId":"201","exchangeId":"101","side":"YES","quantity":n,"limitPrice":"0.600000","expectedPayout":"0.550000","reason":"refreshed_value_exit","expiresAt":iso(60000),"cohortOrigin":{"version":1,"originSha256":"a".repeat(64),"positionsSha256":hash(&positions["101"]),"heldQuantity":self.b().engine().wallet.quantity("101",Side::Yes),"heldCost":moloch_replay::money(self.b().engine().wallet.market_cost("101")),"entries":entries,"exits":exits}}).as_object().unwrap(){e[k]=v.clone();}e}
}

fn passive(f:&F,t:i64,entries:Value,exits:Value,n:u64)->Value{let mut e=f.exit(t,entries,exits,n);e["executionMode"]=json!("passiveValueLimit");e["maximumPassiveQuantity"]=json!(2);e["modelSha256"]=json!("d".repeat(64));e["sourceSha256"]=json!("e".repeat(64));e}
fn ready()->(F,Value){let mut f=F::new();let entry=f.position();let mode=f.mode(7000);f.accept(&mode).unwrap();f.book(10000,"0.400000");(f,entry)}
fn deny(f:&mut F,e:&Value){let head=f.b().durable_head();let report=f.b().engine().report().unwrap();let orders=f.b().engine().order_records();assert!(f.accept(e).is_err());assert_eq!(f.b().durable_head(),head);assert_eq!(f.b().engine().report().unwrap(),report);assert_eq!(f.b().engine().order_records(),orders);}

fn turnover(f:&F,t:i64,entries:Value,exits:Value,n:u64)->Value{
 let mut e=passive(f,t,entries.clone(),exits.clone(),n);let ids=entries.as_array().unwrap().iter().map(|r|r["qid"].as_u64().unwrap()).collect();let sold=exits.as_array().unwrap().iter().map(|r|r["qid"].as_u64().unwrap()).collect();
 let cost=f.b().engine().reviewed_fifo_cost("101",Side::Yes,&ids,&sold,n).unwrap();let worst=moloch_replay::amount(cost["maximumFifoUnitCost"].as_str().unwrap()).unwrap();let floor=worst+5000;
 e["reason"]=json!("reviewed_fifo_profit_turnover");e["pricingObjective"]=json!({"kind":"fifoProfitTurnover","minimumNetGain":"0.005000"});e["forecastExpectedPayout"]=e["expectedPayout"].clone();e["minimumNetSalePrice"]=json!(moloch_replay::money(floor));
 let tick=(floor+4999)/5000*5000;e["limitPrice"]=json!(moloch_replay::money(tick));
 e["pricingBasis"]=json!({"pricingPolicy":"improveAskOneTickFifoFloor","bankHead":e["bankHead"],"positionsSha256":e["expectedPositionSha256"],"quantity":n,"bookSha256":e["bookSha256"],"fifoCostSha256":cost["fifoCostSha256"],"maximumFifoUnitCost":cost["maximumFifoUnitCost"],"minimumNetSalePrice":e["minimumNetSalePrice"],"pricingObjective":e["pricingObjective"],"forecastExpectedPayout":e["expectedPayout"]});e
}
#[test]fn explicit_turnover_preserves_forecast_and_fee_inclusive_expensive_prefix(){let(mut f,buy)=ready();let before=f.b().engine().report().unwrap();let e=turnover(&f,12000,json!([F::row(&buy,"901",2)]),json!([]),2);assert_eq!(e["minimumNetSalePrice"],"0.405001");assert_eq!(e["limitPrice"],"0.410000");assert_eq!(e["expectedPayout"],"0.550000");f.accept(&e).unwrap();let q=f.b().engine().order_records().last().unwrap().clone();let m=&q["reviewedInventoryExit"];assert_eq!(m["forecastExpectedPayout"],"0.550000");assert_eq!(m["minimumNetSalePrice"],"0.405001");assert!(m.get("minimumNetValue").is_none());for k in ["cash","ownedCost","realized","positions","fills"]{assert_eq!(f.b().engine().report().unwrap()[k],before[k]);}}
#[test]fn partial_real_fill_consumes_expensive_leading_lot_and_restart_retains_fee_proof(){let(mut f,buy)=ready();let e=turnover(&f,12000,json!([F::row(&buy,"901",2)]),json!([]),2);f.accept(&e).unwrap();let sell=f.b().engine().order_records().last().unwrap().clone();f.close(&sell,15001,"902",1);assert_eq!(f.b().engine().wallet.market_cost("101"),395000);assert_eq!(f.b().engine().wallet.realized,9999);let report=f.b().engine().report().unwrap();f.bank.take();f.bank=Some(Session::open_live(&f.root.join("bank"),&f.policy,&f.seed).unwrap());assert_eq!(f.b().engine().report().unwrap(),report);f.book(20000,"0.400000");let next=turnover(&f,22000,json!([F::row(&buy,"901",2)]),json!([F::row(&sell,"902",1)]),1);assert_eq!(next["minimumNetSalePrice"],"0.400000");f.accept(&next).unwrap();}
#[test]fn no_averaging_fee_omission_or_changed_provenance_can_lower_native_partial_floor(){for case in ["floor","cost","hash","head","forecast","zero_gain","reason","cap","unknown_objective"]{let(mut f,buy)=ready();let mut e=turnover(&f,12000,json!([F::row(&buy,"901",2)]),json!([]),2);match case{"floor"=>e["limitPrice"]=json!("0.405000"),"cost"=>e["pricingBasis"]["maximumFifoUnitCost"]=json!("0.397500"),"hash"=>e["pricingBasis"]["fifoCostSha256"]=json!("0".repeat(64)),"head"=>e["pricingBasis"]["bankHead"]=json!({}),"forecast"=>e["forecastExpectedPayout"]=json!("0.405001"),"zero_gain"=>e["pricingObjective"]["minimumNetGain"]=json!("0.000000"),"reason"=>e["reason"]=json!("refreshed_value_exit"),"cap"=>e["maximumPassiveQuantity"]=json!(1),_=>e["pricingObjective"]["kind"]=json!("unreviewed")};deny(&mut f,&e);}}
#[test]fn open_pledge_stale_book_and_missing_closed_origin_remain_blocking(){let(mut f,buy)=ready();let e=turnover(&f,12000,json!([F::row(&buy,"901",2)]),json!([]),2);f.accept(&e).unwrap();let again=turnover(&f,15000,json!([F::row(&buy,"901",2)]),json!([]),1);deny(&mut f,&again);let(mut f,buy)=ready();let e=turnover(&f,21001,json!([F::row(&buy,"901",2)]),json!([]),2);deny(&mut f,&e);let mut missing=turnover(&f,12000,json!([F::row(&buy,"901",2)]),json!([]),2);missing["cohortOrigin"]["entries"]=json!([]);deny(&mut f,&missing);}

#[test]fn original_multiunit_fee_rounds_up_per_unit_without_charging_financial_fee_twice(){let mut f=F::new();f.split=false;let buy=f.position();let mode=f.mode(7000);f.accept(&mode).unwrap();f.book(10000,"0.400000");let e=turnover(&f,12000,json!([F::row(&buy,"901",2)]),json!([]),2);assert_eq!(e["pricingBasis"]["maximumFifoUnitCost"],"0.400001");assert_eq!(f.b().engine().wallet.realized,-1);f.accept(&e).unwrap();assert_eq!(f.b().engine().wallet.realized,-1);}
